<?php require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);verify_csrf();$uid=(int)user()['id'];$sid=(int)($_POST['simulation_id']??0);$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');if($rating<1||$rating>5)json_response(['ok'=>false,'message'=>'Choose a rating from 1 to 5.'],422);$stmt=$con->prepare('INSERT INTO simulation_feedback(user_id,simulation_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),created_at=NOW()');$stmt->bind_param('iiis',$uid,$sid,$rating,$comment);$stmt->execute();json_response(['ok'=>true,'message'=>'Thank you for your feedback.','reload'=>true]);
